-- load_purchase_staging.sql
-- Generated by scripts/make_wwi_jobs.py: edit WWI_JOBS there and rerun it, rather than editing this file.
-- Fills WideWorldImportersDW.Integration.Purchase_Staging the way Microsoft's SSIS package would,
-- so Integration.MigrateStagedPurchaseData has input to work on.
-- Run against WideWorldImportersDW. Needs the WideWorldImporters (shop) database on the same server.

SET NOCOUNT ON;

-- 1. Pick a time window: @WindowMonths long, ending @MonthsBack months before the warehouse's last load.
--    The default is the dev batch; jobs/purchase.json changes it for the holdout.
DECLARE @MonthsBack   int = 0;
DECLARE @WindowMonths int = 1;
DECLARE @LastLoad   datetime2(7) = (SELECT [Cutoff Time] FROM Integration.[ETL Cutoff] WHERE [Table Name] = N'Purchase');
DECLARE @NewCutoff  datetime2(7) = DATEADD(month, -@MonthsBack, @LastLoad);
DECLARE @LastCutoff datetime2(7) = DATEADD(month, -@WindowMonths, @NewCutoff);

-- 2. Clear staging (in-memory tables don't allow TRUNCATE)
DELETE FROM Integration.Purchase_Staging;

-- 3. Pull the rows from the shop database. In-memory tables can't be written in the same
--    statement as another user database, so go through a temp table.
CREATE TABLE #rows (
    [Date Key] date,
    [WWI Purchase Order ID] int,
    [Ordered Outers] int,
    [Ordered Quantity] int,
    [Received Outers] int,
    [Package] nvarchar(50),
    [Is Order Finalized] bit,
    [WWI Supplier ID] int,
    [WWI Stock Item ID] int,
    [Last Modified When] datetime2(7)
);

INSERT INTO #rows
EXEC WideWorldImporters.Integration.GetPurchaseUpdates @LastCutoff = @LastCutoff, @NewCutoff = @NewCutoff;

INSERT INTO Integration.Purchase_Staging ([Date Key], [WWI Purchase Order ID], [Ordered Outers], [Ordered Quantity], [Received Outers], [Package], [Is Order Finalized], [WWI Supplier ID], [WWI Stock Item ID], [Last Modified When])
SELECT [Date Key], [WWI Purchase Order ID], [Ordered Outers], [Ordered Quantity], [Received Outers], [Package], [Is Order Finalized], [WWI Supplier ID], [WWI Stock Item ID], [Last Modified When]
FROM #rows;

DROP TABLE #rows;

-- 4. Open a lineage record. MigrateStagedPurchaseData looks for one with no completion time.
EXEC Integration.GetLineageKey @TableName = N'Purchase', @NewCutoffTime = @NewCutoff;

-- 5. Report what got staged
SELECT COUNT(*) AS staged_rows, @LastCutoff AS window_from, @NewCutoff AS window_to
FROM Integration.Purchase_Staging;
